import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  pokemon_cache: defineTable({
    pokemonName: v.string(),
    runId: v.string(),
    data: v.any(),
  }).index("by_name_run", ["pokemonName", "runId"]),
});

import { v } from "convex/values";
import { action, mutation, query } from "./_generated/server";
import { api } from "./_generated/api";

export const getCachedPokemon = query({
  args: { pokemonName: v.string(), runId: v.string() },
  handler: async (ctx, args) => {
    return ctx.db
      .query("pokemon_cache")
      .withIndex("by_name_run", (q) =>
        q.eq("pokemonName", args.pokemonName).eq("runId", args.runId),
      )
      .first();
  },
});

export const cachePokemon = mutation({
  args: { pokemonName: v.string(), runId: v.string(), data: v.any() },
  handler: async (ctx, args) => {
    await ctx.db.insert("pokemon_cache", {
      pokemonName: args.pokemonName,
      runId: args.runId,
      data: args.data,
    });
  },
});

export const getPokemon = action({
  args: { pokemonName: v.string(), runId: v.string() },
  handler: async (ctx, args) => {
    const cached = await ctx.runQuery(api.pokemon.getCachedPokemon, {
      pokemonName: args.pokemonName,
      runId: args.runId,
    });

    if (cached?.data) {
      return cached.data;
    }

    const response = await fetch(
      `https://pokeapi.co/api/v2/pokemon/${args.pokemonName}`,
    );

    if (!response.ok) {
      throw new Error(`Failed to fetch Pokemon: ${response.status}`);
    }

    const data = await response.json();

    await ctx.runMutation(api.pokemon.cachePokemon, {
      pokemonName: args.pokemonName,
      runId: args.runId,
      data,
    });

    return data;
  },
});

import { useState } from "react";
import { useAction } from "convex/react";
import { api } from "../convex/_generated/api";
import "./App.css";

interface PokemonResult {
  name: string;
  weight: number;
}

const runId = import.meta.env.VITE_ZEALT_RUN_ID ?? "";

function App() {
  const [pokemonName, setPokemonName] = useState("");
  const [result, setResult] = useState<PokemonResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const getPokemon = useAction(api.pokemon.getPokemon);

  const handleFetch = async () => {
    const trimmedName = pokemonName.trim().toLowerCase();
    if (!trimmedName) {
      setError("Enter a Pokemon name.");
      setResult(null);
      return;
    }

    setIsLoading(true);
    setError(null);
    setResult(null);

    try {
      const data = await getPokemon({
        pokemonName: trimmedName,
        runId,
      });
      setResult({ name: data.name, weight: data.weight });
    } catch (fetchError) {
      const message =
        fetchError instanceof Error
          ? fetchError.message
          : "Failed to fetch Pokemon.";
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main className="app">
      <h1>Pokemon Cache Lookup</h1>
      <p className="subtitle">
        Cached by Convex for run ID: <span>{runId || "(missing)"}</span>
      </p>
      <div className="controls">
        <label htmlFor="pokemon-input">Pokemon name</label>
        <input
          id="pokemon-input"
          type="text"
          value={pokemonName}
          placeholder="pikachu"
          onChange={(event) => setPokemonName(event.target.value)}
        />
        <button id="fetch-button" type="button" onClick={handleFetch}>
          {isLoading ? "Fetching..." : "Fetch"}
        </button>
      </div>
      <div id="result-display" className="result">
        {error && <p className="error">{error}</p>}
        {result && !error && (
          <div className="card">
            <h2>{result.name}</h2>
            <p>Weight: {result.weight}</p>
          </div>
        )}
        {!result && !error && !isLoading && (
          <p className="hint">Search for a Pokemon to see cached results.</p>
        )}
      </div>
    </main>
  );
}

export default App;

